function text(value) {
  if (value == null) return '';
  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (Array.isArray(value)) return value.map(text).filter(Boolean).join('');
  if (value.plain_text) return String(value.plain_text);
  if (value.name) return String(value.name);
  if (value.title) return text(value.title);
  if (value.rich_text) return text(value.rich_text);
  if (value.select) return text(value.select);
  if (value.checkbox != null) return String(value.checkbox);
  return '';
}
function prop(json, names, type) {
  const wanted = Array.isArray(names) ? names : [names];
  const compact = (value) => String(value || '').replace(/s+/g, '');
  const props = json.properties || {};
  for (const name of wanted) {
    if (json[name] != null) return json[name];
    if (json['property_' + name] != null) return json['property_' + name];
    if (props[name] != null) return props[name];
  }
  for (const [key, value] of Object.entries({ ...json, ...props })) {
    const normalized = compact(key).replace(/^property_/, '');
    if (wanted.some((name) => compact(name) === normalized)) return value;
  }
  if (type) return Object.values(props).find((value) => value?.type === type);
  return undefined;
}
function propText(json, names, type) {
  return text(prop(json, names, type)).trim();
}
function isChecked(json, names) {
  const value = prop(json, names, 'checkbox');
  if (typeof value === 'boolean') return value;
  if (value?.checkbox != null) return Boolean(value.checkbox);
  return text(value).toLowerCase() === 'true';
}
